package org.securemail.relay;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.identity.*;
import org.securemail.ecosystem.protocol.*;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import org.securemail.client.ecosystemauth.IdentityRelayCredentials600;
import org.securemail.client.net.*;
import org.securemail.client.storage.LocalStore;
import org.securemail.protocol.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
/** Real Identity HTTP + Relay TCP + production NetworkService through a synthetic SOCKS5 proxy.
 * Synthetic onion destinations are fixtures; no native Tor or physical-device claim. */
class RelayIdentity600Test {
 @TempDir Path home;IdentityStore authority;IdentityHttpServer http;RelayStore store;RelayServer relay;KeyPair identityKey,relayKey;LocalStore local;RelayConfig config;SocksFixture socks;
 final byte[] password="relay account password 600".getBytes(java.nio.charset.StandardCharsets.UTF_8);
 static KeyPair pair()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}static byte[] key(KeyPair key){return key.getPublic().getEncoded();}
 @BeforeEach void setup()throws Exception{identityKey=pair();relayKey=pair();byte[] audit=new byte[32];new SecureRandom().nextBytes(audit);authority=new IdentityStore(home.resolve("identity/identity.db"),identityKey,audit,Clock.systemUTC());authority.allowRelayService(key(relayKey),IdentityProtocol.id(key(relayKey)));http=new IdentityHttpServer(new InetSocketAddress("127.0.0.1",0),authority,identityKey);http.start();config=new RelayConfig(home.resolve("relay/relay.db"),"127.0.0.1",0,604800000,16_000_000,64_000_000,32,8,true,Set.of());store=new RelayStore(config,Clock.systemUTC());relay=new RelayServer(config,store,Clock.systemUTC(),new PinnedRelaySessionGate600(http.port(),key(identityKey),relayKey));relay.start();local=new LocalStore(home.resolve("local"),"local encrypted vault passphrase".toCharArray(),Clock.systemUTC(),16_000_000,64_000_000);socks=new SocksFixture(relay.port());TorTransport.requireAvailability(()->true);}
 @AfterEach void close()throws Exception{socks.close();local.close();relay.close();store.close();http.close();authority.close();}
 record Enrollment(KeyPair device,KeyPair app,IdentityStore.Session session,Capability cap){}
 Enrollment enroll()throws Exception{KeyPair device=pair(),recovery=pair(),app=pair();long t=System.currentTimeMillis();String n=IdentityProtocol.nonce();byte[] b=IdentityProtocol.registration(authority.audience(),local.identity().publicKey(),key(device),key(recovery),"raven",t,n);IdentityStore.Session session=authority.register(local.identity().publicKey(),key(device),key(recovery),"raven",t,n,local.identity().sign(b),IdentityProtocol.sign(device.getPrivate(),b));return capability(device,app,session,EnumSet.of(Scope.MAIL_READ,Scope.MAIL_SEND,Scope.CONTACTS_READ));}
 Enrollment capability(KeyPair device,KeyPair app,IdentityStore.Session session,Set<Scope> scopes)throws Exception{long t=System.currentTimeMillis();String n=IdentityProtocol.nonce();byte[] b=IdentityProtocol.capabilityRequest(authority.audience(),session.accountId(),session.deviceId(),session.generation(),App.MAIL,key(app),scopes,600000,t,n);Capability cap=authority.issueCapability(session.accountId(),session.deviceId(),session.generation(),App.MAIL,key(app),scopes,600000,t,n,IdentityProtocol.sign(device.getPrivate(),b),IdentityProtocol.sign(app.getPrivate(),b));return new Enrollment(device,app,session,cap);}
 NetworkService network(Enrollment e)throws Exception{NetworkService n=new NetworkService(new TorTransport("127.0.0.1",socks.port()),SocksFixture.ONION,80,local,config.maxCiphertext());if(e!=null)n.identitySession6(new IdentityRelayCredentials600(key(relayKey),key(identityKey),IdentityProtocol.encodeCapability(e.cap),e.app.getPrivate()));return n;}
 void revoke(Enrollment e){long t=System.currentTimeMillis();String n=IdentityProtocol.nonce();authority.login(e.session.accountId(),e.session.deviceId(),t,n,IdentityProtocol.sign(e.device.getPrivate(),IdentityProtocol.login(authority.audience(),e.session.accountId(),e.session.deviceId(),t,n)));}
 Socket connect()throws IOException{Socket s=new Socket(InetAddress.getLoopbackAddress(),relay.port());s.setSoTimeout(6000);return s;}
 byte[] proof(Enrollment e,String nick,byte[] pass)throws IOException{return Binary.encode(out->new IdentityRelayCredentials600(key(relayKey),key(identityKey),IdentityProtocol.encodeCapability(e.cap),e.app.getPrivate()).writeProof(out,e.session.accountId(),nick,pass));}
 int loginProof(byte[] proof,String nick,byte[] pass)throws IOException{try(Socket s=connect()){DataOutputStream out=new DataOutputStream(s.getOutputStream());Binary.header(out);out.writeByte(Operation.LOGIN6.code);Binary.text(out,"");Binary.text(out,nick);Binary.bytes(out,pass);out.write(proof);out.flush();DataInputStream in=new DataInputStream(s.getInputStream());Binary.header(in);return in.readInt();}}
 @Test void actualNetworkServiceRegisters6LogsInFindsAndRevokesViaIdentityGeneration()throws Exception{Enrollment e=enroll();NetworkService n=network(e);n.authenticate("raven",new String(password).toCharArray(),true);assertTrue(n.loggedIn());assertEquals(local.identity().userId(),n.find("raven").userId());assertTrue(socks.hosts.stream().allMatch(x->x.equals(SocksFixture.ONION)));revoke(e);Thread.sleep(300);assertThrows(IOException.class,()->n.find("raven"));assertEquals(1,store.userCount());}
 @Test void legacyUnenrolledAccountWorksButEnrollmentInvalidatesOldLoginAndAlreadyIssuedBearer()throws Exception{NetworkService legacy=network(null);legacy.authenticate("raven",new String(password).toCharArray(),true);assertEquals(local.identity().userId(),legacy.find("raven").userId());Enrollment e=enroll();Thread.sleep(300);assertThrows(IOException.class,()->legacy.find("raven"));NetworkService old=network(null);assertThrows(IOException.class,()->old.authenticate("raven",new String(password).toCharArray(),false));NetworkService modern=network(e);modern.authenticate("raven",new String(password).toCharArray(),false);assertEquals(local.identity().userId(),modern.find("raven").userId());}
 @Test void loginProofIsOneUseAndBindsPasswordNicknameServiceAndAccount()throws Exception{store.register("raven",password,local.identity().publicKey());Enrollment e=enroll();byte[] proof=proof(e,"raven",password);assertEquals(0,loginProof(proof,"raven",password));assertNotEquals(0,loginProof(proof,"raven",password));assertNotEquals(0,loginProof(proof(e,"raven","different password 600".getBytes()),"raven",password));assertNotEquals(0,loginProof(proof(e,"other_name",password),"raven",password));KeyPair wrongService=pair();byte[] wrong=Binary.encode(out->new IdentityRelayCredentials600(key(wrongService),key(identityKey),IdentityProtocol.encodeCapability(e.cap),e.app.getPrivate()).writeProof(out,e.session.accountId(),"raven",password));assertNotEquals(0,loginProof(wrong,"raven",password));}
 @Test void readOnlyCapabilityCannotRegisterOrStoreOrModifyPublicProfile()throws Exception{store.register("raven",password,local.identity().publicKey());Enrollment e=enroll();Enrollment read=capability(e.device,e.app,e.session,EnumSet.of(Scope.MAIL_READ));NetworkService n=network(read);n.authenticate("raven",new String(password).toCharArray(),false);try(Socket s=connect()){DataOutputStream out=new DataOutputStream(s.getOutputStream());Binary.header(out);out.writeByte(Operation.STORE.code);Binary.text(out,n.sessionToken());out.flush();DataInputStream in=new DataInputStream(s.getInputStream());Binary.header(in);assertNotEquals(0,in.readInt());}IdentityRelayCredentials600 creds=new IdentityRelayCredentials600(key(relayKey),key(identityKey),IdentityProtocol.encodeCapability(read.cap),read.app.getPrivate());assertThrows(IOException.class,()->creds.writeRegistrationProof(new DataOutputStream(OutputStream.nullOutputStream()),read.session.accountId(),"raven",password,local.identity().publicKey()));}
 @Test void revokedPublishedRouteIsNotReturnedFromRelayCache()throws Exception{Enrollment e=enroll();NetworkService modern=network(e);modern.authenticate("raven",new String(password).toCharArray(),true);modern.publish(local.identity().route("c".repeat(56)+".onion",80,System.currentTimeMillis()+90000));assertNotNull(modern.find("raven").route());KeyPair other=pair();store.register("other_user",password,key(other));String token;try(Socket s=connect()){DataOutputStream out=new DataOutputStream(s.getOutputStream());Binary.header(out);out.writeByte(Operation.LOGIN.code);Binary.text(out,"");Binary.text(out,"other_user");Binary.bytes(out,password);out.flush();DataInputStream in=new DataInputStream(s.getInputStream());Binary.header(in);assertEquals(0,in.readInt());token=Binary.text(in,64);UserInfo.read(in);}revoke(e);Thread.sleep(300);try(Socket s=connect()){DataOutputStream out=new DataOutputStream(s.getOutputStream());Binary.header(out);out.writeByte(Operation.FIND.code);Binary.text(out,token);Binary.text(out,"raven");out.flush();DataInputStream in=new DataInputStream(s.getInputStream());Binary.header(in);assertEquals(0,in.readInt());assertNull(UserInfo.read(in).route());}}
 @Test void fetchStreamStopsAfterGenerationRevocationAndDoesNotDeletePendingPacket()throws Exception{Enrollment e=enroll();NetworkService n=network(e);n.authenticate("raven",new String(password).toCharArray(),true);KeyPair source=pair();UserInfo sender=store.register("source_user",password,key(source));long now=System.currentTimeMillis();byte[] cipher=new byte[12_000_000];new SecureRandom().nextBytes(cipher);EncryptedPacket unsigned=new EncryptedPacket(UUID.randomUUID().toString(),sender.userId(),sender.nickname(),local.identity().userId(),now,now+600000,86400,Algorithm.AES_256_GCM,new byte[16],new byte[12],cipher,key(source),new byte[0]);EncryptedPacket packet=new EncryptedPacket(unsigned.messageId(),unsigned.senderId(),unsigned.senderNickname(),unsigned.recipientId(),now,unsigned.deliveryDeadline(),86400,unsigned.algorithm(),unsigned.salt(),unsigned.nonce(),unsigned.ciphertext(),unsigned.senderPublicKey(),IdentityProtocol.sign(source.getPrivate(),Signatures.digest(unsigned)));store.store(sender,packet);try(Socket s=connect()){s.setReceiveBufferSize(32768);s.setSoTimeout(12000);DataOutputStream out=new DataOutputStream(s.getOutputStream());Binary.header(out);out.writeByte(Operation.FETCH.code);Binary.text(out,n.sessionToken());out.flush();DataInputStream in=new DataInputStream(s.getInputStream());Binary.header(in);assertEquals(0,in.readInt());assertTrue(in.readBoolean());revoke(e);Thread.sleep(300);assertThrows(IOException.class,()->PacketCodec.read(in,config.maxCiphertext()));}assertEquals(1,store.packetCount());}
 @Test void storeWriteRollsBackIfGenerationCheckFailsAtCommit()throws Exception{UserInfo user=store.register("raven",password,local.identity().publicKey());long now=System.currentTimeMillis();EncryptedPacket packet=local.identity().signPacket(new EncryptedPacket(UUID.randomUUID().toString(),user.userId(),user.nickname(),user.userId(),now,now+600000,86400,Algorithm.AES_256_GCM,new byte[16],new byte[12],new byte[128],user.publicKey(),new byte[0]));int[] checks={0};assertThrows(IOException.class,()->store.store(user,packet,()->{if(++checks[0]>=2)throw new IOException("Injected generation revocation before durable commit");}));assertEquals(2,checks[0]);assertEquals(0,store.packetCount());}
 @Test void registrationRollsBackIfFreshAuthorizationFailsAfterPasswordKdf()throws Exception{KeyPair fresh=pair();int[] checks={0};assertThrows(IOException.class,()->store.register("not_committed",password,key(fresh),()->{if(++checks[0]>=2)throw new IOException("Injected revocation before commit");}));assertNull(store.find("not_committed"));assertEquals(2,checks[0]);}
 static final class SocksFixture implements AutoCloseable{
  static final String ONION="a".repeat(56)+".onion";final ServerSocket listener=new ServerSocket(0,16,InetAddress.getLoopbackAddress());final ExecutorService workers=Executors.newFixedThreadPool(12);final Set<Socket> sockets=ConcurrentHashMap.newKeySet();final List<String> hosts=new CopyOnWriteArrayList<>();final int relayPort;volatile boolean closed;
  SocksFixture(int relayPort)throws IOException{this.relayPort=relayPort;workers.submit(()->{while(!closed)try{Socket s=listener.accept();sockets.add(s);workers.submit(()->handle(s));}catch(IOException e){if(closed)return;}});}
  int port(){return listener.getLocalPort();}void handle(Socket client){try(client){client.setSoTimeout(6000);DataInputStream in=new DataInputStream(client.getInputStream());OutputStream out=client.getOutputStream();if(in.readUnsignedByte()!=5)return;in.readNBytes(in.readUnsignedByte());out.write(new byte[]{5,0});out.flush();if(in.readUnsignedByte()!=5||in.readUnsignedByte()!=1||in.readUnsignedByte()!=0||in.readUnsignedByte()!=3)return;String host=new String(in.readNBytes(in.readUnsignedByte()),java.nio.charset.StandardCharsets.US_ASCII);in.readUnsignedShort();hosts.add(host);if(!host.equals(ONION))throw new IOException("Fixture destination rejected");try(Socket upstream=new Socket(InetAddress.getLoopbackAddress(),relayPort)){sockets.add(upstream);out.write(new byte[]{5,0,0,1,127,0,0,1,0,0});out.flush();workers.submit(()->{try{in.transferTo(upstream.getOutputStream());}catch(IOException ignored){}});upstream.getInputStream().transferTo(out);out.flush();sockets.remove(upstream);}}catch(IOException ignored){}finally{sockets.remove(client);}}
  public void close()throws IOException{closed=true;listener.close();for(Socket s:sockets)try{s.close();}catch(IOException ignored){}workers.shutdownNow();}
 }
}
